import Foundation
import PrevisCore
@testable import ShotsMedia
import Testing

/// A4's starter camera moves, generated by `CameraMoves.marks` the way Blockout's `tests/unit/camera-moves.test.ts`
/// builds them: from a camera at (0, 1.6, 6) looking down −Z, around a man standing at the origin or walking down −Z
/// at 2 m/s, over about 8 s, and around the same walk eased in and out by a quarter, as Blockout's actor marks are by
/// default. Runs in CI; the suite below replays Blockout's own output.
@Suite("camera legs for A4's starter moves")
struct CameraLegStarterMoveTests {
    enum Subject: CaseIterable { case standing, walking, easedWalking }

    @Test(arguments: Subject.allCases)
    func everyStarterMoveReadsAsItsName(subject: Subject) throws {
        let catalog = try ContentCatalog.bundled()
        for id in catalog.starter.cameraMoves {
            let facts = try Self.facts(id, subject: subject, catalog: catalog)
            let legs = facts.cameraLegs, label = "\(id) \(subject): \(legs)"
            PresetReading.expectOrdered(legs, frames: facts.frameCount, label)
            PresetReading.expectNamed(id, walking: subject != .standing, legs: legs, label)
            PresetReading.expectDescribed(id, legs: legs, swing: .large, label)
            #expect(legs.map(\.move) == Self.moves(id, walking: subject != .standing), "\(label)")
        }
    }

    /// Each starter move reads as its name and nothing more, or a follow move as a track (a hold around someone
    /// standing), except where Blockout builds the move of parts: the whip pan holds, whips and holds again; the
    /// side dolly comes in past the subject, round him and away; and a crash-in barely moves at first, its distance
    /// falling with the cube of time, before it rushes in: a hold first around someone standing, a track around
    /// someone walking.
    private static func moves(_ id: String, walking: Bool) -> [CameraMove] {
        switch id {
        case "whip-pan": [.static, .panLeft, .static]
        case "side-dolly-past": [.push, .orbitLeft, .pull]
        case "crash-in": [walking ? .track : .static, .push]
        default:
            PresetReading.following.contains(id) ? [walking ? .track : .static] : PresetReading.named[id]
                .map { [$0] } ?? []
        }
    }

    /// A follow move round a right-angle corner is one track. The walker's facing snaps onto his new path at the
    /// corner mark, and between its marks, 0.83 s apart, the camera swings round to its place in his new frame; at
    /// every mark it is beside, ahead of or behind him where the move puts it.
    @Test func followsRoundASharpCornerAreOneTrack() throws {
        let catalog = try ContentCatalog.bundled()
        let end = 140.0 / 24, corner = [(0, Vec3.zero), (3, Vec3(0, 0, -6)), (end, Vec3(-6, 0, -6))]
        for id in catalog.starter.cameraMoves where PresetReading.following.contains(id) {
            let legs = try Self.facts(id, frames: 141, walk: corner, ease: 0, catalog: catalog).cameraLegs
            #expect(legs.map(\.move) == [.track], "\(id): \(legs)")
        }
    }

    private static func facts(_ id: String, subject: Subject, catalog: ContentCatalog) throws -> PromptFacts {
        let end = 191.0 / 24
        return try facts(
            id,
            frames: 192,
            walk: subject == .standing ? [] : [(0, .zero), (end, Vec3(0, 0, -2 * end))],
            ease: subject == .easedWalking ? 0.25 : 0,
            catalog: catalog
        )
    }

    /// The move generated around a man standing at the origin, or walking through `walk`'s points at its times with
    /// each mark eased by `ease`.
    private static func facts(
        _ id: String, frames: Int, walk: [(Double, Vec3)], ease: Double, catalog: ContentCatalog
    ) throws -> PromptFacts {
        var scene = PrevisScene.make(
            id: "scene_moves", name: id, takeID: "take_moves", shotID: "shot_moves", cameraMarkID: "cam_0"
        )
        scene.shots[0].frameCount = frames
        scene.shots[0].camera.marks = [CameraMark(
            id: "cam_0", time: 0, hold: 0, easeIn: 0, easeOut: 0, position: Vec3(0, 1.6, 6), pan: 0, tilt: 0,
            roll: 0, focalLength: 35
        )]
        scene.entities = [PrevisEntity(
            id: "ent_subject", assetID: "person.man", name: "Subject",
            placement: Placement(position: .zero, heading: 0, scale: 1)
        )]
        if !walk.isEmpty {
            scene.blocking[0].tracks = [Track(entityID: "ent_subject", marks: walk.enumerated().map { index, point in
                ActorMark(
                    id: "m\(index)", time: point.0, hold: 0, easeIn: ease, easeOut: ease, position: point.1,
                    gait: .walk
                )
            })]
        }
        let move = try CameraMoves.marks(
            id, scene: scene, shotID: scene.shots[0].id, subjects: ["ent_subject"], catalog: catalog
        )
        scene.shots[0].camera.marks = move.marks
        scene.shots[0].camera.trackIDs = move.trackIDs
        return try ShotPromptCompiler.facts(scene: scene, shotID: scene.shots[0].id, catalog: catalog)
    }
}

/// What a preset should read as, around a standing or a walking subject, checked the same way for Blockout's own
/// vectors and for A4's generated moves.
enum PresetReading {
    /// The move each preset is named for. Moves Blockout names after the path rather than the framing (boom-over,
    /// flyover, drone-strafe-reveal) are checked only for not circling.
    static let named: [String: CameraMove] = [
        "slow-push-in": .push, "crash-in": .push, "creep-in-low": .push, "pull-back-reveal": .pull,
        "drone-rise-pullback": .pull, "orbit-90-left": .orbitLeft, "orbit-90-right": .orbitRight,
        "orbit-180": .orbitLeft, "orbit-360": .orbitLeft, "arc-and-push": .orbitLeft, "orbit-45-low": .orbitLeft,
        "orbit-45-high": .orbitLeft, "spiral-in-descend": .orbitLeft, "spiral-out-ascend": .orbitLeft,
        "drone-orbit-high": .orbitLeft, "dutch-orbit": .orbitLeft, "side-dolly-past": .orbitLeft,
        "crane-up-reveal": .craneUp, "pedestal-up": .craneUp, "pedestal-up-slow": .craneUp,
        "crane-down-intro": .craneDown, "top-down-descend": .craneDown, "static-pan-across": .panLeft,
        "slow-tilt-reveal": .tiltUp, "vertigo-dolly-zoom": .push, "push-in-dutch-roll": .push,
    ]
    /// Blockout's "follow" presets ride with the subject: a track around a walking one, nothing at all around one
    /// that stands still.
    static let following: Set = [
        "follow-behind", "lead-the-subject", "side-track-left", "side-track-right", "lead-follow-front",
        "low-lead-tilt-up", "overhead-track-follow",
    ]

    /// The reading covers the shot in order, with no two neighbours alike and no sliver of a hold.
    static func expectOrdered(_ legs: [PromptFacts.CameraLeg], frames: Int, _ label: String) {
        #expect(legs.first?.fromFrame == 0 && legs.last?.toFrame == frames - 1, "\(label)")
        for (before, after) in zip(legs, legs.dropFirst()) {
            #expect(before.toFrame == after.fromFrame && before.move != after.move, "\(label)")
        }
        #expect(legs.count == 1 || legs.allSatisfy { $0.move != .static || $0.toFrame - $0.fromFrame >= 6 })
    }

    /// The longest leg is the preset's move, following a walking subject when it moves relative to him; a follow
    /// preset is a track, or a hold around someone standing; a pass over or past a subject never circles it.
    static func expectNamed(_ id: String, walking: Bool, legs: [PromptFacts.CameraLeg], _ label: String) {
        let dominant = legs.max { $0.toFrame - $0.fromFrame < $1.toFrame - $1.fromFrame }
        if let move = named[id] {
            #expect(dominant?.move == move, "\(label)")
            if [.push, .pull, .orbitLeft, .orbitRight, .craneUp, .craneDown].contains(move) {
                #expect(dominant?.also.contains(.track) == walking, "\(label)")
            }
        }
        if ["flyover", "drone-strafe-reveal", "boom-over"].contains(id) {
            #expect(!legs.contains { [.orbitLeft, .orbitRight].contains($0.move) }, "\(label)")
        }
        if following.contains(id) {
            #expect(legs.map(\.move) == [walking ? .track : .static], "\(label)")
        }
    }

    /// Whips, snaps, dolly-zooms, dutch rolls and slow tilts read as Blockout describes them.
    static func expectDescribed(_ id: String, legs: [PromptFacts.CameraLeg], swing: MoveAmplitude, _ label: String) {
        switch id {
        case "whip-pan":
            // "Hold on the subject, then a violent 90° pan in ~0.4s mid-shot, then settle."
            #expect(legs.map(\.move) == [.static, .panLeft, .static], "\(label)")
            #expect(legs.dropFirst().first.map { $0.speed == .fast && $0.amplitude == swing } == true, "\(label)")
        case "snap-zoom-punch", "crash-zoom-out":
            let zoom: CameraMove = id == "snap-zoom-punch" ? .zoomIn : .zoomOut
            #expect(
                legs.map(\.move) == [.static, zoom, .static] && legs.dropFirst().first?.speed == .fast, "\(label)"
            )
        case "vertigo-dolly-zoom":
            // "Push in while the lens widens so the subject stays the same size."
            #expect(legs.count == 1 && legs.first?.also.contains(.zoomOut) == true, "\(label)")
        case "dutch-orbit", "push-in-dutch-roll":
            #expect(legs.count == 1 && legs.first?.also.contains(.rollCounterclockwise) == true, "\(label)")
        case "slow-tilt-reveal":
            #expect(legs.map(\.speed) == [.slow], "\(label)")
        default:
            break
        }
    }
}

/// Blockout's camera-move presets as its own engine generated them (`golden-vectors.v1.json`, the file A4's
/// vector tests read through `PREVIS_VECTORS`), each played around the subject Blockout built it for.
@Suite(
    "camera legs against Blockout's presets",
    .enabled(if: ProcessInfo.processInfo.environment["PREVIS_VECTORS"] != nil)
)
struct CameraLegOracleTests {
    @Test func everyPresetReadsAsItsName() throws {
        let catalog = try ContentCatalog.bundled()
        for vector in try Self.vectors().camera {
            let facts = try Self.facts(vector, catalog: catalog)
            let legs = facts.cameraLegs, label = "\(vector.id) \(vector.subject) \(vector.duration) s: \(legs)"
            // Over the flying subject, aim lock's swings straight above it are no roll.
            if vector.subject == "fly", ["top-down-descend", "overhead-track-follow"].contains(vector.id) {
                #expect(!legs.contains { [.rollClockwise, .rollCounterclockwise].contains($0.move) }, "\(label)")
            }
            PresetReading.expectOrdered(legs, frames: facts.frameCount, label)
            // The flying subject's own 1 m bob reads as small crane legs (a known limit), so its moves aren't named.
            guard vector.subject != "fly" else { continue }
            PresetReading.expectNamed(vector.id, walking: vector.subject == "walk", legs: legs, label)
        }
    }

    @Test func zoomsRollsAndWhipsReadAsBlockoutDescribesThem() throws {
        let catalog = try ContentCatalog.bundled()
        for vector in try Self.vectors().camera {
            let legs = try Self.facts(vector, catalog: catalog).cameraLegs, label = "\(vector.id): \(legs)"
            if vector.subject == "fly", vector.id != "whip-pan" { continue }
            // Level, a whip pan swings the view 90°; tilted up 60° at the flying subject, about 41°.
            PresetReading.expectDescribed(
                vector.id,
                legs: legs,
                swing: vector.subject == "fly" ? .medium : .large,
                label
            )
        }
    }

    private static func vectors() throws -> GoldenVectors {
        let path = try #require(ProcessInfo.processInfo.environment["PREVIS_VECTORS"])
        return try JSONDecoder().decode(GoldenVectors.self, from: Data(contentsOf: URL(fileURLWithPath: path)))
    }

    private static func facts(_ vector: GoldenVectors.Camera, catalog: ContentCatalog) throws -> PromptFacts {
        let scene = presetScene(vector, track: catalog.cameraMoves.first { $0.id == vector.id }?.track ?? false)
        return try ShotPromptCompiler.facts(scene: scene, shotID: scene.shots[0].id, catalog: catalog)
    }
}

/// The subjects Blockout's extraction built its vectors around: standing at the origin, walking down −Z at
/// 1.4 m/s, or flying 5 m tall along (3t, 8 + sin t, −12t).
func presetScene(_ vector: GoldenVectors.Camera, track: Bool) -> PrevisScene {
    let subjectID = "ent_subject"
    let frameCount = FrameGrid.snapUp(Int((vector.duration * Double(FrameGrid.fps)).rounded()) + 1)
    var scene = PrevisScene.make(
        id: "scene_oracle", name: vector.id, takeID: "take_oracle", shotID: "shot_oracle", cameraMarkID: "cam_0"
    )
    let flying = vector.subject == "fly"
    scene.entities = [PrevisEntity(
        id: subjectID,
        assetID: flying ? "animal.bird" : "person.man",
        name: "Subject",
        placement: Placement(position: .zero, heading: 0, scale: flying ? 5 / 0.25 : 1.75 / 1.78)
    )]
    func at(_ time: Double) -> Vec3 {
        switch vector.subject {
        case "walk": Vec3(0, 0, -1.4 * time)
        case "fly": Vec3(3 * time, 8 + sin(time), -12 * time)
        default: .zero
        }
    }
    let times: [Double] = switch vector.subject {
    case "walk": [0, vector.duration]
    case "fly": (0 ... Int(vector.duration * 24)).map { Double($0) / 24 }
    default: []
    }
    scene.blocking[0].tracks = times.isEmpty ? [] : [Track(entityID: subjectID, marks: times.enumerated().map {
        ActorMark(
            id: "m\($0.offset)", time: $0.element, hold: 0, easeIn: 0, easeOut: 0, position: at($0.element),
            gait: flying ? .stand : .walk
        )
    })]
    scene.shots[0].frameCount = frameCount
    scene.shots[0].camera.trackIDs = track ? [subjectID] : []
    scene.shots[0].camera.marks = vector.marks.enumerated().map { index, mark in
        CameraMark(
            id: "cam_\(index)", time: mark.time, hold: mark.hold, easeIn: mark.easeIn, easeOut: mark.easeOut,
            position: Vec3(mark.position.x, mark.position.y, mark.position.z), pan: mark.pan, tilt: mark.tilt,
            roll: mark.roll, focalLength: mark.focalLength
        )
    }
    return scene
}

/// The camera part of `golden-vectors.v1.json`.
struct GoldenVectors: Decodable {
    struct Camera: Decodable {
        var id: String, subject: String, duration: Double
        var marks: [GoldenMark]
    }

    var camera: [Camera]
}

struct GoldenMark: Decodable {
    struct Point: Decodable { var x: Double, y: Double, z: Double }
    var time: Double, hold: Double, easeIn: Double, easeOut: Double
    var position: Point
    var pan: Double, tilt: Double, roll: Double, focalLength: Double
}
